function persist(){const safe=copy(state);function redact(value){if(!value||typeof value!=='object')return;for(const k of Object.keys(value)){if(/password|auth.?key|token|secret|private.?key/i.test(k))value[k]='';else redact(value[k]);}}redact(safe);for(const sub of safe.subscriptions)sub.url='https://example.com/subscription';const privateContent=JSON.stringify(safe).length<14500?{routaList:safe}:null;try{window.openai?.setWidgetState?.({modelContent:{design:'亮色代理列表 V4.3 · 直接关闭编辑',page:state.page,resourceTab:view.resource,proxies:state.proxies.map(p=>({name:p.name,mode:MODE[p.mode],enabled:p.enabled,nic:NIC[actualNic(p)]}))},privateContent}).catch(()=>{});}catch{}}
function tailnetNic(p){if(p.mode==='direct')return null;const t=p.target.kind==='shared'?scheme(p.target.id):p.target;if(!t)return null;const ids=t.kind==='node'?[t.id||t.node]:t.kind==='strategy'?expandedMembers(t.members):[];return ids.length&&ids.every(id=>node(id)?.ts)&&new Set(ids.map(id=>node(id).ts.nic)).size===1?node(ids[0]).ts.nic:null;}
