function renderSettings(){settingsDraft??=copy(state.settings);const s=settingsDraft,top=tabs([['general','常规与界面'],['core','内核与测速']],view.settings,'v4-settings-tab','设置分类');const row=control=>`<div class="v4-setrow">${control}</div>`;let body=view.settings==='general'?row(select('v4-interface-mode','界面模式',state.settings.interfaceMode,[['Full','完整版'],['Simple','简洁版']]))+row(toggleField('v4-start','开机启动',s.start))+row(toggleField('v4-auto-connect','启动后自动连接',s.autoConnect))+row(select('v4-close','关闭窗口时',s.tray?'tray':'exit',[['tray','最小化到托盘'],['exit','退出程序']])):row('<div class="l-field"><span class="l-fieldhead">内核</span><strong>应用内置 mihomo</strong><span class="v4-sub">'+esc(state.core.version)+'</span></div>')+row(field('v4-controller-port','控制 API 端口',s.controllerPort,'number','min="1" max="65535"'))+row(select('v4-test-interval','自动测速间隔',String(s.testInterval),[['0','关闭'],['5','5 分钟'],['10','10 分钟'],['30','30 分钟'],['60','1 小时']]))+row(field('v4-test-url','测速 URL',s.testUrl,'url'))+row(button('打开日志目录','v4-log-files','','l-btn'));return header('设置','',button('故障诊断','v4-diagnostics','','l-btn'))+pane(top,`<div class="v4-pad"><div class="l-card">${body}</div><div id="v4-settings-error" class="l-pickererror" role="alert"></div></div>`,`<span id="v4-settings-state">设置将应用到同一份配置</span>${button('保存设置','v4-save-settings','','l-btn primary')}`);}
